"""Generated bytes only; optional loopback HTTP, no model, decoder or OEM data."""
import http.client
import json
import os
from pathlib import Path
import tempfile
import threading
import unittest
from unittest.mock import patch

from edge.backup_library import BackupLibrary, LibraryError, fingerprint


class CopyOnlyBackupTest(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.source = self.root / 'source'; self.source.mkdir()
        self.recording = self.source / 'generated.dav'
        self.recording.write_bytes(b'Generated bytes only, not an OEM recording.')
        os.utime(self.recording, (900, 900))
        self.now = 1000.0
        self.library = self.make()
        self.addCleanup(lambda: self.library.close())
        self.library.configure(dict(source_folder=str(self.source), backup_folder=str(self.root / 'backup'),
                                    max_storage_gib=100, reserve_gib=2, settle_seconds=60, recursive=False))

    def make(self):
        return BackupLibrary(None, self.root / 'settings', supervise=False, clock=lambda: self.now)

    def test_copy_and_reopen_need_no_analysis_catalog_or_worker(self):
        before = fingerprint(self.recording)
        self.assertFalse(self.library.status()['analysis_configured'])
        self.assertFalse(self.library.status()['active'])
        self.library.start(dict(analyze=False, model='', rules=''))
        self.library.scan()
        self.assertEqual(self.library.status()['items'], [])
        self.now += 61; self.library.scan(); self.library._analysis_tick()
        row = self.library.status()['items'][0]
        self.assertEqual((row['state'], row['sha256']), ('saved', before))
        self.assertIsNone(self.library.analysis)
        self.assertEqual(fingerprint(self.recording), before)
        with self.library.open_artifact(row['id'], 'source')[0] as stream:
            self.assertEqual(stream.read(), self.recording.read_bytes())
        self.library.close(); self.library = self.make()
        self.assertFalse(self.library.status()['active'])
        self.assertEqual(self.library.status()['items'][0]['id'], row['id'])

    def test_api_cannot_enable_or_retry_analysis_without_a_model(self):
        with self.assertRaises(LibraryError) as raised:
            self.library.start(dict(analyze=True, model='invented', rules='invented'))
        self.assertEqual(raised.exception.code, 'ANALYSIS_DISABLED')
        self.assertFalse(self.library.status()['active'])
        with self.assertRaises(LibraryError) as raised:
            self.library.retry({'id':'0' * 32})
        self.assertEqual(raised.exception.code, 'ANALYSIS_DISABLED')
        self.assertEqual(self.library.status()['items'], [])

    @unittest.skipUnless(os.environ.get('DVR_TEST_SOCKETS') == '1', 'Optional generated loopback HTTP check')
    def test_real_http_copy_without_model_keeps_auth_and_rejects_analysis(self):
        from edge.local_service import LocalServer
        with LocalServer(0, None, self.root, library=self.library) as server:
            thread = threading.Thread(target=server.serve_forever, daemon=True)
            thread.start()
            def request(path, body=None, token=None):
                headers = {'Origin':server.origin}
                if token is not None: headers['X-DVR-Token'] = token
                if body is not None: headers['Content-Type'] = 'application/json'
                connection = http.client.HTTPConnection('127.0.0.1', server.server_port, timeout=5)
                try:
                    connection.request('POST' if body is not None else 'GET', path,
                                       json.dumps(body) if body is not None else None, headers)
                    response = connection.getresponse()
                    return response.status, json.loads(response.read())
                finally:
                    connection.close()
            try:
                status, session = request('/api/library/session')
                self.assertEqual(status, 200)
                self.assertFalse(session['analysis_enabled'])
                self.assertEqual(session['models'], [])
                self.assertEqual(request('/api/library/status')[0], 403)
                token = session['token']
                status, error = request('/api/library/start', dict(analyze=True, model='fake', rules='fake'), token)
                self.assertEqual((status, error['error']['code']), (409, 'ANALYSIS_DISABLED'))
                self.assertEqual(request('/api/library/start', dict(analyze=False, model='', rules=''), token)[0], 202)
                self.library.scan(); self.now += 61; self.library.scan()
                status, report = request('/api/library/status', token=token)
                self.assertEqual(status, 200)
                self.assertEqual(len(report['items']), 1)
                self.assertEqual(report['items'][0]['state'], 'saved')
                self.assertFalse(report['analysis_configured'])
                self.assertEqual(request('/api/library/stop', {}, token)[0], 200)
            finally:
                server.shutdown(); thread.join(5)
                self.assertFalse(thread.is_alive())

    def test_existing_saved_review_is_readable_without_reloading_its_model(self):
        self.library.start(dict(analyze=False, model='', rules=''))
        self.library.scan(); self.now += 61; self.library.scan()
        row = self.library.status()['items'][0]
        review = self.library.store / row['id'] / 'review.json'
        data = {'receipt': {'source_sha256':row['sha256']}, 'trace': {'source_sha256':row['sha256']}}
        review.write_text(json.dumps(data))
        self.library.db.execute("UPDATE items SET state='completed', review_sha256=? WHERE id=?", (fingerprint(review), row['id']))
        self.library.db.commit()
        self.library.close(); self.library = self.make()
        with self.library.open_artifact(row['id'], 'result')[0] as stream:
            self.assertEqual(json.load(stream), data)
        self.assertFalse(self.library.status()['active'])


if __name__ == '__main__':
    unittest.main()
